function Assert-True{param([bool]$Condition,[string]$Message)if(-not$Condition){throw $Message}}
function Test-Utf8NoBom{param([string]$Path)$B=[IO.File]::ReadAllBytes($Path);if($B.Length-ge3-and$B[0]-eq239-and$B[1]-eq187-and$B[2]-eq191){throw "UTF-8 BOM forbidden: $Path"};[void](New-Object Text.UTF8Encoding($false,$true)).GetString($B)}
function Test-Png{param([string]$Path)$B=[IO.File]::ReadAllBytes($Path);$S=[byte[]](137,80,78,71,13,10,26,10);if($B.Length-le8){throw "PNG empty: $Path"};for($I=0;$I-lt8;$I++){if($B[$I]-ne$S[$I]){throw "PNG signature invalid: $Path"}}}
