            foreach($M in @('FIRST_POINT_DIAGNOSTIC','HIGH_FREQUENCY_INTERCEPT')){$Class=if($M-eq'FIRST_POINT_DIAGNOSTIC'){'LAB_SCREENING_HEURISTIC'}else{'HFR_ESTIMATOR'};$HfrRows.Add([PSCustomObject][ordered]@{sample_id=$C.sample_id;replicate_id=$C.replicate_id;case_id=$C.case_id;method=$M;method_class=$Class;HFR_ohm='';HFR_uncertainty_ohm='';selected_point_count=0;selected_original_rows='';frequency_min_Hz='';frequency_max_Hz='';intercept_model='NONE';residual_metric='';high_frequency_coverage_status='NOT_ASSESSED';inductive_artifact_status='NOT_ASSESSED';duplicate_frequency_status='NOT_ASSESSED';fit_quality_status='NOT_ASSESSED';status='EXPERIMENTAL_INPUT_INCOMPLETE';failure_reason='missing experimental file or critical provenance';source_file=$C.file_path;equivalent_circuit=$C.equivalent_circuit;fitting_software=$C.fitting_software;fit_file=$C.fit_file;Rs_ohm=$C.Rs_ohm;Rs_standard_error_ohm=$C.Rs_standard_error_ohm;fit_quality_metric=$C.fit_quality_metric;fit_quality_value=$C.fit_quality_value;source_reference=$C.source_reference;contract_status=$C.status;notes=$C.notes;detail='case classification is independent of RUN_STATE'})};continue
