    $Rep=@();foreach($C in $Manifest|Where-Object fixture_group -in @('AGREE','DISAGREE')){$Rep+=[PSCustomObject]@{sample_id=$C.sample_id;method=$C.intercept_method;replicate_id=$C.replicate_id;case_id=$C.case_id;hfr_ohm=$Estimator[$C.case_id].EstimateOhm}};$Consensus=@(Get-M03A2ReplicateConsensus $Rep);Assert-True ($Consensus.Count-eq2-and@($Consensus|Where-Object sample_id -eq S_DISAGREE)[0].replicate_count-eq3) 'replicate consensus contract';Add-Log 'REPLICATE_CONSENSUS|PASS|individual=5|consensus_rows=2|outlier_retained=1'
